using System.Diagnostics;
using System.Reflection;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text.Json;

var assemblyPath = Path.GetFullPath(args[0]);
var registryField = args[1];
var outputPath = Path.GetFullPath(args[2]);
if (File.Exists(outputPath)) {
    throw new InvalidOperationException("Measurement already exists.");
}
var assembly = AssemblyLoadContext.Default.LoadFromAssemblyPath(assemblyPath);
var owner = assembly.GetType("CanDoItAll.Processes.Persistence.ProcessRuntimeRootSequenceLocks", throwOnError: true)!;
var method = owner.GetMethod("AcquireAsync", BindingFlags.Public | BindingFlags.Static)!;
var acquire = method.CreateDelegate<Func<IEnumerable<Guid>, CancellationToken, Task<IDisposable>>>();
var registry = owner.GetField(registryField, BindingFlags.NonPublic | BindingFlags.Static)!.GetValue(null)!;
var countProperty = registry.GetType().GetProperty("Count")!;
int Retained() => (int)countProperty.GetValue(registry)!;
var single = new[] { Guid.NewGuid() };
for (var i = 0; i < 2000; i++) {
    using var lease = await acquire(single, CancellationToken.None);
}
var rows = new List<object>();
foreach (var scenario in new[] { "same-root", "unique-roots", "parallel-roots", "contended-root", "parallel-churn" }) {
    var workers = scenario.StartsWith("parallel", StringComparison.Ordinal) || scenario == "contended-root" ? 8 : 1;
    var iterations = scenario == "contended-root" ? 500 : 5000;
    var keys = Enumerable.Range(0, workers).Select(_ => new[] { Guid.NewGuid() }).ToArray();
    var beforeCount = Retained();
    var beforeBytes = GC.GetTotalAllocatedBytes(precise: true);
    var elapsed = Stopwatch.StartNew();
    await Task.WhenAll(Enumerable.Range(0, workers).Select(worker => Task.Run(async () => {
        for (var i = 0; i < iterations; i++) {
            var ids = scenario switch {
                "same-root" or "contended-root" => single,
                "unique-roots" or "parallel-churn" => new[] { Guid.NewGuid() },
                _ => keys[worker]
            };
            using var lease = await acquire(ids, CancellationToken.None);
            if (scenario == "contended-root") {
                await Task.Yield();
            }
        }
    })));
    elapsed.Stop();
    rows.Add(new {
        scenario, workers, operations = workers * iterations, elapsedMs = elapsed.Elapsed.TotalMilliseconds,
        allocatedBytes = GC.GetTotalAllocatedBytes(precise: true) - beforeBytes,
        retainedBefore = beforeCount, retainedAfter = Retained()
    });
}
var proof = new {
    recordedUtc = DateTimeOffset.UtcNow, runtime = Environment.Version.ToString(), processId = Environment.ProcessId,
    assemblySha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(assemblyPath))), registryField, rows,
    limitation = "Focused same-machine registry experiment; excludes SQL, provider work and sustained workload capacity. Repeat in fresh processes; raw timings are not a service throughput guarantee."
};
await File.WriteAllTextAsync(outputPath, JsonSerializer.Serialize(proof, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine(JsonSerializer.Serialize(proof));
